// Server-only JSON repository abstraction.
// All data access goes through the functions in this file so that swapping the
// storage backend (e.g. to Supabase) later only requires changing this file.

import "server-only"
import { promises as fs } from "node:fs"
import path from "node:path"
import type { AppUser, DiscordConfig, Gallery, GalleryImage, Tag, AuditEntry, RoleName } from "./types"
import { AddGalleryImageSchema, ReorderGalleryImagesSchema, parseOrThrow } from "./validate"

const DB_DIR = path.join(process.cwd(), "database")

// ---------------------------------------------------------------------------
// Write queue — prevents concurrent read-modify-write race conditions on
// JSON files. Each file gets its own queue so reads/writes to different files
// don't block each other unnecessarily.
// ---------------------------------------------------------------------------
const writeQueues = new Map<string, Promise<void>>()

function enqueueWrite(file: string, fn: () => Promise<void>): Promise<void> {
  const prev = writeQueues.get(file) ?? Promise.resolve()
  const next = prev.then(fn).catch((err) => {
    console.warn("[db] write queue error for", file, (err as Error).message)
  })
  writeQueues.set(file, next)
  return next
}

// Simple in-memory cache so we don't re-read JSON on every request.
type Cache<T> = { value: T | null; loaded: boolean }

const cache = {
  users: { value: null, loaded: false } as Cache<{ users: AppUser[] }>,
  tags: { value: null, loaded: false } as Cache<{ tags: Tag[] }>,
  galleries: { value: null, loaded: false } as Cache<{ galleries: Gallery[] }>,
  announcement: { value: null, loaded: false } as Cache<AnnouncementBanner | null>,
}

async function loadJson<T>(file: string): Promise<T> {
  const raw = await fs.readFile(path.join(DB_DIR, file), "utf-8")
  return JSON.parse(raw) as T
}

async function writeJson<T>(file: string, data: T): Promise<void> {
  return enqueueWrite(file, async () => {
    try {
      await fs.writeFile(path.join(DB_DIR, file), JSON.stringify(data, null, 2), "utf-8")
    } catch (err) {
      console.warn("[v0] db: filesystem write failed, continuing with in-memory state only:", (err as Error).message)
    }
  })
}

// Helper to invalidate a specific cache entry (used after admin writes)
export function invalidateCache(key: keyof typeof cache) {
  cache[key].loaded = false
  cache[key].value = null
}

/* ---------- Discord config ---------- */

export function getDiscordConfig(): DiscordConfig {
  const role_id = [
    { name: "69Bath" as RoleName, id: (process.env.DISCORD_ROLE_69BATH_ID ?? "").trim(), hierarchy_level: 1 },
    { name: "99Bath" as RoleName, id: (process.env.DISCORD_ROLE_99BATH_ID ?? "").trim(), hierarchy_level: 2 },
    { name: "199Bath" as RoleName, id: (process.env.DISCORD_ROLE_199BATH_ID ?? "").trim(), hierarchy_level: 3 },
    { name: "299Bath" as RoleName, id: (process.env.DISCORD_ROLE_299BATH_ID ?? "").trim(), hierarchy_level: 4 },
    { name: "699Bath" as RoleName, id: (process.env.DISCORD_ROLE_699BATH_ID ?? "").trim(), hierarchy_level: 5 },
  ].filter((r) => r.id !== "")

  return {
    ownerid_user: process.env.DISCORD_OWNER_ID ?? "",
    role_id,
  }
}

/* ---------- Users ---------- */

async function loadUsers(): Promise<AppUser[]> {
  if (!cache.users.loaded) {
    const raw = await loadJson<{ users: AppUser[] }>("users.json")
    cache.users.value = raw
    cache.users.loaded = true
  }
  return (cache.users.value as { users: AppUser[] }).users
}

export async function getUserById(userId: string): Promise<AppUser | null> {
  const users = await loadUsers()
  return users.find((u) => u.user_id === userId) ?? null
}

/** Admin: get ALL users (including banned) */
export async function getAllUsers(): Promise<AppUser[]> {
  return loadUsers()
}

export async function saveUser(user: AppUser): Promise<void> {
  const users = await loadUsers()
  const idx = users.findIndex((u) => u.user_id === user.user_id)
  if (idx === -1) users.push(user)
  else users[idx] = user
  ;(cache.users.value as { users: AppUser[] }).users = users
  await writeJson("users.json", { users })
}

export async function upsertDiscordUser(input: {
  user_id: string
  username: string
  discord_tag: string
  avatar: string | null
  active_roles: RoleName[]
}): Promise<{ user: AppUser; rolesBefore: RoleName[] }> {
  const existing = await getUserById(input.user_id)
  const now = new Date().toISOString()
  const expires = new Date(Date.now() + 15 * 60 * 1000).toISOString()

  if (existing) {
    const rolesBefore = existing.roles_cache.active_roles
    existing.username = input.username
    existing.discord_tag = input.discord_tag
    existing.avatar = input.avatar
    existing.last_login = now
    existing.login_count += 1
    existing.roles_cache = {
      active_roles: input.active_roles,
      last_synced: now,
      cache_expires_at: expires,
    }
    await saveUser(existing)
    return { user: existing, rolesBefore }
  }

  const newUser: AppUser = {
    user_id: input.user_id,
    username: input.username,
    discord_tag: input.discord_tag,
    avatar: input.avatar,
    is_banned: false,
    ban_reason: null,
    first_login: now,
    last_login: now,
    login_count: 1,
    roles_cache: {
      active_roles: input.active_roles,
      last_synced: now,
      cache_expires_at: expires,
    },
    link_usage: {},
    audit_log: [],
    favorites: [],
  }
  await saveUser(newUser)
  return { user: newUser, rolesBefore: [] }
}

export async function appendAudit(userId: string, entry: AuditEntry): Promise<void> {
  const user = await getUserById(userId)
  if (!user) return
  user.audit_log.push(entry)
  if (user.audit_log.length > 500) user.audit_log = user.audit_log.slice(-500)
  await saveUser(user)
}

export async function toggleUserFavorite(userId: string, galleryId: string): Promise<string[]> {
  const user = await getUserById(userId)
  if (!user) return []
  const set = new Set(user.favorites ?? [])
  if (set.has(galleryId)) set.delete(galleryId)
  else set.add(galleryId)
  user.favorites = Array.from(set)
  await saveUser(user)
  return user.favorites
}

export async function mergeUserFavorites(userId: string, ids: string[]): Promise<string[]> {
  const user = await getUserById(userId)
  if (!user) return []
  const merged = new Set<string>([...(user.favorites ?? []), ...ids])
  user.favorites = Array.from(merged)
  await saveUser(user)
  return user.favorites
}

export async function recordLinkCopy(userId: string, galleryId: string, linkId: string): Promise<void> {
  const user = await getUserById(userId)
  if (!user) return
  const now = new Date().toISOString()
  user.link_usage[galleryId] = user.link_usage[galleryId] ?? {}
  const prev = user.link_usage[galleryId][linkId]
  user.link_usage[galleryId][linkId] = {
    copy_count: (prev?.copy_count ?? 0) + 1,
    last_copied_at: now,
  }
  user.audit_log.push({
    action: "copy_link",
    gallery_id: galleryId,
    link_id: linkId,
    timestamp: now,
  })
  await saveUser(user)
}

/* ---------- Tags ---------- */

export async function listTags(): Promise<Tag[]> {
  if (!cache.tags.loaded) {
    const raw = await loadJson<{ tags: Tag[] }>("tag.json")
    cache.tags.value = raw
    cache.tags.loaded = true
  }
  return (cache.tags.value as { tags: Tag[] }).tags
}

/** Admin: save all tags */
export async function saveTags(tags: Tag[]): Promise<void> {
  if (cache.tags.value) {
    (cache.tags.value as { tags: Tag[] }).tags = tags
  }
  invalidateCache("tags")
  await writeJson("tag.json", { tags })
  // Reload cache
  cache.tags.value = { tags }
  cache.tags.loaded = true
}

/* ---------- Galleries ---------- */

async function loadGalleries(): Promise<Gallery[]> {
  if (!cache.galleries.loaded) {
    const raw = await loadJson<{ galleries: Gallery[] }>("gallery.json")
    cache.galleries.value = raw
    cache.galleries.loaded = true
  }
  return (cache.galleries.value as { galleries: Gallery[] }).galleries
}

export async function listGalleries(): Promise<Gallery[]> {
  const all = await loadGalleries()
  return [...all]
    .filter((g) => g.is_active)
    .sort((a, b) => {
      if (a.is_pinned !== b.is_pinned) return a.is_pinned ? -1 : 1
      return new Date(b.uploaded_at).getTime() - new Date(a.uploaded_at).getTime()
    })
}

/** Admin: get ALL galleries including inactive */
export async function getAllGalleriesRaw(): Promise<Gallery[]> {
  return loadGalleries()
}

export async function getGalleryById(id: string): Promise<Gallery | null> {
  const all = await loadGalleries()
  return all.find((g) => g.id === id) ?? null
}

/** Admin: save galleries */
export async function saveGalleries(galleries: Gallery[]): Promise<void> {
  invalidateCache("galleries")
  await writeJson("gallery.json", { galleries })
  cache.galleries.value = { galleries }
  cache.galleries.loaded = true

  // Auto-sync tag gallery_ids and gallery_count
  try {
    const tags = await listTags()
    const tagGalleryMap = new Map<string, string[]>()
    tags.forEach((t) => tagGalleryMap.set(t.id, []))
    galleries
      .filter((g) => g.is_active)
      .forEach((g) => {
        g.tags.forEach((tagId) => {
          if (tagGalleryMap.has(tagId)) tagGalleryMap.get(tagId)!.push(g.id)
        })
      })
    let changed = false
    tags.forEach((t) => {
      const ids = tagGalleryMap.get(t.id) ?? []
      if (t.gallery_count !== ids.length) {
        t.gallery_ids = ids
        t.gallery_count = ids.length
        changed = true
      }
    })
    if (changed) {
      invalidateCache("tags")
      await writeJson("tag.json", { tags })
      cache.tags.value = { tags }
      cache.tags.loaded = true
    }
  } catch { /* tag counts are display-only */ }
}

export async function incrementGalleryView(id: string): Promise<void> {
  const all = await loadGalleries()
  const g = all.find((x) => x.id === id)
  if (!g) return
  g.stats.total_views += 1
  await writeJson("gallery.json", { galleries: all })
}

export async function incrementLinkCopy(galleryId: string, linkId: string): Promise<void> {
  const all = await loadGalleries()
  const g = all.find((x) => x.id === galleryId)
  if (!g) return
  const link = g.links.find((l) => l.id === linkId)
  if (!link) return
  link.total_copies += 1
  g.stats.total_copies += 1
  await writeJson("gallery.json", { galleries: all })
}

// ---------------------------------------------------------------------------
// Gallery Image management — add / remove / reorder images
// ---------------------------------------------------------------------------

/**
 * เพิ่มรูปใหม่เข้า gallery โดยใช้ URL
 * Validation ทำผ่าน AddGalleryImageSchema (Zod) — ป้องกัน javascript:/data: URI
 * throws Error ถ้า input ไม่ผ่าน schema
 */
export async function addGalleryImage(
  galleryId: string,
  rawInput: { url: string; caption?: string }
): Promise<GalleryImage | null> {
  const input = parseOrThrow(AddGalleryImageSchema, rawInput, "AddGalleryImage")

  const all = await loadGalleries()
  const g = all.find((x) => x.id === galleryId)
  if (!g) return null

  // Ensure images array exists (backward-compat)
  if (!g.images) g.images = []

  const maxOrder = g.images.reduce((m, img) => Math.max(m, img.sort_order), -1)
  const newImage: GalleryImage = {
    id: crypto.randomUUID(),
    url: input.url,
    caption: input.caption,
    sort_order: maxOrder + 1,
    added_at: new Date().toISOString(),
  }

  g.images.push(newImage)
  g.updated_at = new Date().toISOString()

  // Keep backward-compat thumbnail field in sync with first image
  const sorted = [...g.images].sort((a, b) => a.sort_order - b.sort_order)
  g.thumbnail = sorted[0].url

  invalidateCache("galleries")
  await writeJson("gallery.json", { galleries: all })
  cache.galleries.value = { galleries: all }
  cache.galleries.loaded = true

  return newImage
}

/** ลบรูปออกจาก gallery */
export async function removeGalleryImage(galleryId: string, imageId: string): Promise<boolean> {
  const all = await loadGalleries()
  const g = all.find((x) => x.id === galleryId)
  if (!g || !g.images) return false

  const before = g.images.length
  g.images = g.images.filter((img) => img.id !== imageId)
  if (g.images.length === before) return false

  // Re-normalize sort_order after removal
  g.images.sort((a, b) => a.sort_order - b.sort_order).forEach((img, i) => {
    img.sort_order = i
  })

  // Sync thumbnail
  if (g.images.length > 0) {
    g.thumbnail = g.images[0].url
  }
  g.updated_at = new Date().toISOString()

  invalidateCache("galleries")
  await writeJson("gallery.json", { galleries: all })
  cache.galleries.value = { galleries: all }
  cache.galleries.loaded = true

  return true
}

/**
 * เปลี่ยนลำดับรูปใน gallery
 * รับ array ของ imageId (UUID) ตามลำดับที่ต้องการใหม่
 * throws Error ถ้า orderedImageIds ว่างหรือ id ไม่ใช่ UUID
 */
export async function reorderGalleryImages(galleryId: string, rawOrderedImageIds: string[]): Promise<boolean> {
  const { orderedImageIds } = parseOrThrow(
    ReorderGalleryImagesSchema,
    { orderedImageIds: rawOrderedImageIds },
    "ReorderGalleryImages"
  )
  const all = await loadGalleries()
  const g = all.find((x) => x.id === galleryId)
  if (!g || !g.images) return false

  orderedImageIds.forEach((id, idx) => {
    const img = g.images.find((i) => i.id === id)
    if (img) img.sort_order = idx
  })

  // Sync thumbnail ให้เป็นรูปแรกหลัง reorder
  const sorted = [...g.images].sort((a, b) => a.sort_order - b.sort_order)
  if (sorted.length > 0) g.thumbnail = sorted[0].url

  g.updated_at = new Date().toISOString()

  invalidateCache("galleries")
  await writeJson("gallery.json", { galleries: all })
  cache.galleries.value = { galleries: all }
  cache.galleries.loaded = true

  return true
}

/* ---------- Announcement Banner ---------- */

export interface AnnouncementBanner {
  message: string
  type: "info" | "warning" | "success"
  created_at: string
}

export async function getAnnouncementBanner(): Promise<AnnouncementBanner | null> {
  if (!cache.announcement.loaded) {
    try {
      const raw = await fs.readFile(path.join(DB_DIR, "announcement.json"), "utf-8")
      cache.announcement.value = JSON.parse(raw)
    } catch {
      // File doesn't exist yet — no announcement
      cache.announcement.value = null
    }
    cache.announcement.loaded = true
  }
  return cache.announcement.value as AnnouncementBanner | null
}

export async function setAnnouncementBanner(banner: AnnouncementBanner | null): Promise<void> {
  cache.announcement.value = banner
  cache.announcement.loaded = true
  try {
    if (banner === null) {
      await fs.unlink(path.join(DB_DIR, "announcement.json")).catch(() => {})
    } else {
      await fs.writeFile(path.join(DB_DIR, "announcement.json"), JSON.stringify(banner, null, 2), "utf-8")
    }
  } catch (err) {
    console.warn("[db] announcement write failed:", err)
  }
}
/* ---------- Announcement Note (Rich Notepad) ---------- */

export interface AnnouncementNote {
  /** Raw HTML content from the rich editor (TipTap / ProseMirror) */
  content_html: string
  /** Plain text fallback for search / preview */
  content_text: string
  updated_at: string
  updated_by: string
}

const NOTE_FILE = "note.json"

export async function getAnnouncementNote(): Promise<AnnouncementNote | null> {
  try {
    const raw = await fs.readFile(path.join(DB_DIR, NOTE_FILE), "utf-8")
    return JSON.parse(raw) as AnnouncementNote
  } catch {
    return null
  }
}

export async function saveAnnouncementNote(note: AnnouncementNote): Promise<void> {
  try {
    await fs.writeFile(path.join(DB_DIR, NOTE_FILE), JSON.stringify(note, null, 2), "utf-8")
  } catch (err) {
    console.warn("[db] note write failed:", err)
  }
}